var TAO_MAX_PER_TYPE = 12;   // 同じ種類が 1 レイヤーに大量にあるとき、値を読むのは先頭の何個までか

var taoDone = false;

function taoId(node) {
    var p = [0, 0];
    try { p = node.GetNodeGraphPosition(); } catch (e) {}
    if (!p || p.length < 2) p = [0, 0];
    return node.GetName() + "@" + Math.round(p[0]) + "," + Math.round(p[1]);
}

function taoLinks(node, countFn, getFn) {
    var out = [];
    try {
        var n = node[countFn]();
        for (var i = 0; i < n; i++) {
            var other = node[getFn](i);
            if (other) out.push(taoId(other));
        }
    } catch (e) {}
    return out;
}

// 1 つのパラメータを読む。数値で読めればそれを、だめなら文字列を返す。
function taoRead(node, name) {
    var f, s;
    try { f = node.GetFloat(name); } catch (e) {}
    if (typeof f === "number" && isFinite(f)) {
        try { s = node.GetString(name); } catch (e) {}
        if (typeof s === "string" && s !== "" && s !== ("" + f)) return [f, s];
        return f;
    }
    try { s = node.GetString(name); } catch (e) {}
    if (typeof s === "string" && s !== "") return s;
    return undefined;
}

function taoProps(node, type) {
    var ids = TAO_T[type];
    if (!ids) return undefined;
    var out = {}, found = 0;
    for (var k = 0; k < ids.length; k++) {
        var full = TAO_S[ids[k]];
        var v = taoRead(node, full);
        if (v === undefined) {                       // 「グループ.名前」で読めなければ名前だけで試す
            var dot = full.indexOf(".");
            if (dot > 0) v = taoRead(node, full.substring(dot + 1));
        }
        if (v !== undefined) { out[full] = v; found++; }
    }
    return found ? out : undefined;
}

function taoDump() {
    Log("TAO|BEGIN|" + JSON.stringify({ version: GetNotchVersion(), script: 3 }));
    var numLayers = Document.GetNumLayers();
    var propTested = false;
    for (var l = 0; l < numLayers; l++) {
        var layer = Document.GetLayer(l);
        if (!layer) continue;
        Log("TAO|LAYER|" + JSON.stringify({
            index: l, name: layer.GetName(),
            start: layer.GetStartTime(), end: layer.GetEndTime()
        }));
        var nodes = layer.GetNodes();
        var seen = {};
        for (var i = 0; i < nodes.length; i++) {
            var node = nodes[i];
            if (!node) continue;
            try {
                var rec = { layer: l, id: taoId(node), name: node.GetName() };
                try { rec.type = node.GetCategoryAndType(); } catch (e) { rec.type = "?"; }
                try { rec.pos = node.GetNodeGraphPosition(); } catch (e) {}
                try { rec.visible = node.GetVisible(); } catch (e) {}
                try { rec.start = node.GetStartTime(); rec.end = node.GetEndTime(); } catch (e) {}
                rec.children = taoLinks(node, "GetNumChildren", "GetChild");
                rec.parents = taoLinks(node, "GetNumParents", "GetParent");
                rec.embeds = taoLinks(node, "GetNumEmbeds", "GetEmbed");
                seen[rec.type] = (seen[rec.type] || 0) + 1;
                if (seen[rec.type] <= TAO_MAX_PER_TYPE && rec.type !== "Scripting::Javascript Node") {
                    if (!propTested) { Log("TAO|PROPTEST|" + JSON.stringify({ node: rec.name, type: rec.type })); propTested = true; }
                    var p = taoProps(node, rec.type);
                    if (p) rec.props = p;
                }
                Log("TAO|NODE|" + JSON.stringify(rec));
            } catch (e) { Log("TAO|SKIP|" + JSON.stringify({ layer: l, index: i, error: "" + e })); }
        }
    }
    Log("TAO|END|");
}

function Update() {
    if (taoDone) return;
    taoDone = true;
    taoDump();
}
